  "summary": "科恩兄弟执导的西部 anthology 电影，由六个独立短篇组成。从歌唱牛仔的荒诞冒险到淘金者的诗意孤独，从马车乘客的死亡对话到边境女子的求生挣扎，每个故事都以不同的调性探索美国西部的暴力、偶然与宿命。影片以精致的画面构图和黑色幽默消解了西部片的英雄神话，取而代之的是对人类处境冷峻而温柔的凝视。六个故事如同六首挽歌，唱尽了边疆传说中未被讲述的另一面。",
