  "summary": "以唐代骠国献乐为历史背景，讲述一支由多国成员组成的乐团从缅甸长途跋涉至长安献乐的传奇旅程。剧集融合公路片、悬疑与民族风情，沿途遭遇追杀、背叛与文化碰撞。于荣光执导并主演，对西南少数民族文化与东南亚风情的还原用心考究。剧集避开宫廷权谋套路，以音乐与友谊为主线，传递出开放包容的盛唐气象。作为国产剧中罕见的跨国题材作品，它以真诚的态度完成了一次文化寻根之旅。",
