  "summary": "独立心理悬疑片。年轻女子露西在一次车祸后失去部分记忆，在重建身份的过程中发现自己过去的叙述与他人记忆存在巨大出入。影片以不可靠叙事和碎片化剪辑模拟失忆者的认知混乱，观众与主角一同在真假难辨的记忆迷宫中寻找锚点。导演刻意避免给出明确答案，让观众体验记忆本身的脆弱性与建构性。是一部挑战观影习惯的实验性作品。",
  "review": "它不给你一个确定的露西，而是让你明白：我们每个人都是自己记忆的 unreliable narrator。",
