  "summary": "保罗·莱尼执导的默片经典，改编自雨果同名小说。贵族后裔格温普兰幼年被毁容成为永久笑脸的畸形人，在马戏团以「笑面人」身份表演谋生。他与盲女黛娅相爱，却在恢复爵位后被上流社会当作玩物。影片以表现主义的视觉风格和康拉德·韦特的传奇表演，将雨果对社会虚伪与人性尊严的批判转化为震撼的银幕形象。那张永恒的笑脸成为电影史上最著名的面孔之一，直接影响了小丑角色的诞生。",
  "review": "那张被刀刻出的笑容里，藏着比任何台词都更响亮的人类悲鸣。",
