  "summary": "《鬼灭之刃》剧场版三部曲首章，承接TV版锻刀村篇之后。鬼杀队闯入鬼舞辻无惨的根据地无限城，与上弦之鬼展开最终决战。本章聚焦炭治郎、义勇等人与上弦之三猗窝座的宿命对决，ufotable以顶级的作画与演出将漫画中最激烈的战斗段落搬上银幕。作为系列走向终局的开端，影片在保持热血战斗的同时深化了角色之间的羁绊与牺牲的重量。",
  "review": "当水之呼吸与火之神神乐在无限城中交汇，你知道这场战斗承载的不只是胜负，还有所有逝去之人的意志。",
