  "summary": "杜琪峰执导的黑帮史诗。香港最大社团「和联胜」两年一度选举话事人，阿乐与大D两大候选人展开明争暗斗。影片摒弃了传统港产黑帮片的枪战与义气，转而以冷峻写实的笔触描绘权力交接中的算计、背叛与制度性暴力。任达华与梁家辉的表演内敛而充满张力，结尾的湖边杀人戏以近乎纪录片的冷静呈现了权力的本质。被誉为华语黑帮片的巅峰，可与《教父》对话。",
  "review": "没有兄弟情义的热血，只有权力机器冰冷的运转声——这才是黑社会真正的样子。",
