  "summary": "皮克斯经典动画。小丑鱼马林的妻子和大部分卵被梭鱼吞噬，唯一幸存的儿子尼莫被人类捕获带到悉尼牙医诊所。过度保护的马林踏上横跨大洋的寻子之旅，途中结识健忘的蓝唐王鱼多莉。尼莫则在鱼缸中学会勇敢与独立。影片以绚丽的海洋世界、动人的父子情感和「放手才是爱」的成长主题感动了全球观众，多莉成为皮克斯最受欢迎的配角之一。",
  "review": "它教会了无数父母一件事：爱不是紧紧抓住，而是相信他能游过那片海。",
