  "summary": "高畑勋执导的吉卜力作品，讲述二战末期神户兄妹清太与节子在空袭中失去母亲后艰难求生的故事。影片以冷静克制的笔触描绘饥饿、疾病与尊严的丧失，没有任何煽情配乐或英雄化处理。萤火虫的微光成为短暂美好的象征，也是生命脆弱性的隐喻。作为反战动画的巅峰之作，它拒绝将战争归咎于单一敌人，而是呈现普通人被时代碾碎的无力感。观看体验极其痛苦，但这正是它不可替代的价值所在。",
  "review": "一部你不该错过但也不想再看的电影，它的痛是必要的。",
