  "summary": "迪士尼文艺复兴期巅峰之作。聪慧独立的乡村女孩贝儿为救父亲自愿留在被诅咒的城堡，与化为野兽的王子朝夕相处。在魔法玫瑰凋零之前，两人学会了超越外表看见彼此的灵魂。影片以百老汇级别的歌曲、华丽的动画技术和「内在美」的永恒主题成为动画史上的里程碑，是首部获得奥斯卡最佳影片提名的动画电影。贝儿作为迪士尼第一位真正意义上的知识分子公主，影响了此后数十年的女性角色塑造。",
  "review": "三十二年过去，它依然是关于「看见」最美的寓言——真正的魔法不是变回人形，而是学会用心去看。",
