  "summary": "小学时带头欺凌听障少女西宫硝子的石田将也，在多年后成为被孤立的一方。他决定在自杀前找到硝子，两人在赎罪与自我厌恶中重新学习如何与人连接。京都动画以细腻作画呈现声音与沉默的视觉化表达，手语与表情刻画极为用心。影片不美化霸凌者也不神化受害者，对'原谅'与'自我接纳'的探讨复杂而诚实。虽有争议，但它对沟通障碍的描绘超越了简单的道德训诫，抵达了人与人之间理解的艰难本质。",
  "review": "一部让人不舒服却无法移开视线的电影，它的温柔藏在刺痛里。",
