  "summary": "改编自英国绘本大师Raymond Briggs同名作品的动画电影，以作者父母Ethel与Ernest的真实人生为蓝本，描绘一对普通伦敦夫妇从1928年相遇到1971年相继离世的平凡一生。手绘风格质朴温暖，透过洗碗、吵架、养儿、老去等日常碎片折射出二战、福利国家建设、社会变革等宏大历史对个体生命的深刻塑造。情感克制却直击人心后劲极强，历史与个人的交织浑然天成毫无说教感。叙事平淡对偏好戏剧冲突者可能觉得闷，但正是这种对平凡的忠实记录使其成为动画史上最动人的父母肖像，用最朴素的线条画出了最深沉的爱。",
  "review": "用最朴素的线条画出最深沉的爱，是动画史上最动人的父母肖像。",
